import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.List;
import sailpoint.object.ProvisioningPlan;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import sailpoint.object.ProvisioningPlan.AttributeRequest;
import sailpoint.object.ProvisioningResult;

ProvisioningResult result = new ProvisioningResult();
boolean hasFailures = false;

String serializeToXml(Object value) {
  if (value == null) {
    return null;
  }
  try {
    String methodName = "to" + "Xml";
    Method serializer = value.getClass().getMethod(methodName);
    Object output = serializer.invoke(value);
    if (output != null) {
      return String.valueOf(output);
    }
  } catch (Exception ignored) {
    // Fallback is handled by caller.
  }
  return null;
}

String normalizeDetailsForOperations(String payload) {
  if (payload == null) {
    return "";
  }
  String normalized = payload.replace("\r\n", "\n").replace("\r", "\n");
  byte[] bytes = normalized.getBytes(StandardCharsets.UTF_8);
  return "base64:" + Base64.getEncoder().encodeToString(bytes);
}

void writeOperationRecord(String operationName, String payload) throws SQLException {
  PreparedStatement localStatement = null;
  try {
    localStatement = connection.prepareStatement(
      "INSERT INTO Operations (OPERATION, DATE, DETAILS) VALUES (?, ?, ?)"
    );
    localStatement.setString(1, operationName);
    localStatement.setTimestamp(2, new Timestamp(System.currentTimeMillis()));
    localStatement.setString(3, normalizeDetailsForOperations(payload));
    localStatement.executeUpdate();
  } finally {
    if (localStatement != null) {
      localStatement.close();
    }
  }
}

boolean shouldSplitAttribute(AttributeRequest attributeRequest) {
  if (attributeRequest == null || attributeRequest.getName() == null) {
    return false;
  }
  String attributeName = attributeRequest.getName().trim();
  return "ROLES".equalsIgnoreCase(attributeName) || "LOGIN_AREAS".equalsIgnoreCase(attributeName);
}

String safeString(Object value) {
  return value == null ? "" : String.valueOf(value);
}

String escapeXmlText(String value) {
  if (value == null) {
    return "";
  }
  String escaped = value;
  escaped = escaped.replace("&", "&amp;");
  escaped = escaped.replace("<", "&lt;");
  escaped = escaped.replace(">", "&gt;");
  escaped = escaped.replace("\"", "&quot;");
  escaped = escaped.replace("'", "&apos;");
  return escaped;
}

String buildConsolidatedAccountDetails(AccountRequest account, ProvisioningPlan plan) {
  if (account == null) {
    String fallbackPlan = serializeToXml(plan);
    return fallbackPlan == null ? "" : fallbackPlan;
  }

  StringBuilder details = new StringBuilder();
  details.append("<AccountRequest application='").append(escapeXmlText(safeString(account.getApplicationName())));
  details.append("' op='").append(escapeXmlText(safeString(account.getOperation())));
  details.append("' nativeIdentity='").append(escapeXmlText(safeString(account.getNativeIdentity())));
  details.append("'>");

  List attributeRequests = account.getAttributeRequests();
  if (attributeRequests != null && !attributeRequests.isEmpty()) {
    for (Object attributeObj : attributeRequests) {
      AttributeRequest attributeRequest = (AttributeRequest) attributeObj;
      if (shouldSplitAttribute(attributeRequest)) {
        continue;
      }
      details.append("\n  <AttributeRequest name='")
        .append(escapeXmlText(safeString(attributeRequest == null ? null : attributeRequest.getName())))
        .append("' op='")
        .append(escapeXmlText(safeString(attributeRequest == null ? null : attributeRequest.getOperation())))
        .append("' value='")
        .append(escapeXmlText(safeString(attributeRequest == null ? null : attributeRequest.getValue())))
        .append("'/>");
    }
  }
  details.append("\n</AccountRequest>");
  return details.toString();
}

String buildSplitAttributeDetails(AccountRequest account, AttributeRequest attributeRequest, ProvisioningPlan plan) {
  String xmlPayload = serializeToXml(attributeRequest);
  if (xmlPayload == null || xmlPayload.trim().length() == 0) {
    StringBuilder fallback = new StringBuilder();
    fallback.append("<AttributeRequest parentOp='").append(escapeXmlText(safeString(account == null ? null : account.getOperation())));
    fallback.append("' parentNativeIdentity='").append(escapeXmlText(safeString(account == null ? null : account.getNativeIdentity())));
    fallback.append("' name='").append(escapeXmlText(safeString(attributeRequest == null ? null : attributeRequest.getName())));
    fallback.append("' op='").append(escapeXmlText(safeString(attributeRequest == null ? null : attributeRequest.getOperation())));
    fallback.append("' value='").append(escapeXmlText(safeString(attributeRequest == null ? null : attributeRequest.getValue())));
    fallback.append("'/>");
    xmlPayload = fallback.toString();
  }
  return xmlPayload == null ? "" : xmlPayload;
}

if (plan == null) {
  result.setStatus(ProvisioningResult.STATUS_COMMITTED);
  return result;
}

List accountRequests = plan.getAccountRequests();
if (accountRequests == null || accountRequests.isEmpty()) {
  result.setStatus(ProvisioningResult.STATUS_COMMITTED);
  return result;
}

for (Object accountObj : accountRequests) {
  AccountRequest account = (AccountRequest) accountObj;
  try {
    String operation = "AccountRequest.Unknown";
    if (account != null && account.getOperation() != null) {
      operation = "AccountRequest." + String.valueOf(account.getOperation());
    }

    String accountDetails = buildConsolidatedAccountDetails(account, plan);
    if (accountDetails == null) {
      accountDetails = "";
    }
    writeOperationRecord(operation, accountDetails);

    List attributeRequests = account == null ? null : account.getAttributeRequests();
    if (attributeRequests != null && !attributeRequests.isEmpty()) {
      for (Object attributeObj : attributeRequests) {
        AttributeRequest attributeRequest = (AttributeRequest) attributeObj;
        if (!shouldSplitAttribute(attributeRequest)) {
          continue;
        }

        String attributeOperation = "AttributeRequest.Unknown";
        if (attributeRequest != null && attributeRequest.getOperation() != null) {
          attributeOperation = "AttributeRequest." + String.valueOf(attributeRequest.getOperation());
        }

        String attributeDetails = buildSplitAttributeDetails(account, attributeRequest, plan);

        writeOperationRecord(attributeOperation, attributeDetails);
      }
    }
  } catch (SQLException e) {
    hasFailures = true;
    result.addError(e);
  } catch (Exception e) {
    hasFailures = true;
    result.addError(e);
  }
}

if (hasFailures) {
  result.setStatus(ProvisioningResult.STATUS_FAILED);
} else {
  result.setStatus(ProvisioningResult.STATUS_COMMITTED);
}

return result;
